int[] scores = [72, 95, 40, 88];      // four numbers (arrays: a later lesson)

foreach (var s in scores)             // s takes each score in turn
{
    string grade;
    if (s >= 90) grade = "A";
    else if (s >= 70) grade = "B";
    else grade = "F";
    Console.Write($"{s}:{grade} ");    // 72:B 95:A 40:F 88:B
}
Console.WriteLine();

for (int i = 0; i < scores.Length; i++)   // Length = 4, so i = 0, 1, 2, 3
{
    if (scores[i] < 50) continue;         // skip low scores
    if (scores[i] > 90) break;            // stop at the first top score
    Console.Write(i + " ");               // 0
}

