class Account
{
    private string _owner;           // fields: each account's own data
    private decimal _balance;
    public static int Count { get; private set; } // shared by all accounts

    public Account(string owner)     // constructor: runs on new Account(...)
    {
        _owner = owner;
        Count++;                     // ++ adds 1
    }

    public void Deposit(decimal amount)
    {
        if (amount <= 0) throw new ArgumentOutOfRangeException(nameof(amount)); // refuse: stop with an error
        _balance += amount;
    }
    public void Withdraw(decimal amount) => _balance -= amount;
    public string Describe() => $"{_owner}: {_balance}";
}

