static int ParseAge(string s)
{
    int age = int.Parse(s);                 // throws FormatException for "abc"
    if (age < 0) throw new ArgumentOutOfRangeException(nameof(s), "negative age");
    return age;
}

string[] inputs = ["42", "abc", "-3"];
foreach (var input in inputs)
{
    try
    {
        Console.WriteLine($"ok {ParseAge(input)}");
    }
    catch (FormatException)
    {
        Console.WriteLine($"not a number: {input}");
    }
    catch (ArgumentException ex) when (ex.ParamName == "s")  // ParamName: which parameter was bad
    {
        Console.WriteLine("invalid: negative age");
    }
    finally { Console.WriteLine("checked"); }   // runs every time
}
// ok 42 / checked / not a number: abc / checked / invalid: negative age / checked

