using System.Diagnostics;

static async Task<int> FetchAsync(string name, int ms)
{
    await Task.Delay(ms);             // pretend I/O: no thread is blocked
    Console.WriteLine($"{name} done");
    return ms;
}

var sw = Stopwatch.StartNew();
int a = await FetchAsync("A", 300);   // sequential
int b = await FetchAsync("B", 300);
Console.WriteLine($"sequential {sw.ElapsedMilliseconds} ms"); // at least 600 ms

sw.Restart();
Task<int> t1 = FetchAsync("C", 300);  // start both...
Task<int> t2 = FetchAsync("D", 300);
int[] results = await Task.WhenAll(t1, t2); // ...then await together
Console.WriteLine($"concurrent {sw.ElapsedMilliseconds} ms, sum {results.Sum()}");
// concurrent about 300 ms, sum 600

try { await Task.FromException(new InvalidOperationException("boom")); }
catch (InvalidOperationException ex) { Console.WriteLine(ex.Message); } // boom

static void Work()
{
    using var a = new Resource("A");
    using var b = new Resource("B");
    a.Use();
    b.Use();
}   // disposed in reverse order here

Work();
// using A / using B / disposed B / disposed A

try
{
    using var c = new Resource("C");
    throw new InvalidOperationException();
}
catch (InvalidOperationException) { Console.WriteLine("caught"); }
// disposed C / caught

class Resource(string name) : IDisposable
{
    public void Use() => Console.WriteLine($"using {name}");
    public void Dispose() => Console.WriteLine($"disposed {name}");
}

