static void Report(string label)
    => Console.WriteLine($"{label}: gen0={GC.CollectionCount(0)} gen1={GC.CollectionCount(1)} gen2={GC.CollectionCount(2)}");

Report("start");
for (int i = 0; i < 1_000_000; i++)
{
    var tmp = new byte[100];            // short-lived: dies in gen 0
}
Report("after 1M small allocs");        // many gen0, few or no gen2

var small = new object();
var large = new byte[100_000];          // >= 85,000 bytes: LOH
Console.WriteLine(GC.GetGeneration(small)); // 0
Console.WriteLine(GC.GetGeneration(large)); // 2 (LOH is logically gen 2)

GC.Collect();                           // for demonstration only
Console.WriteLine(GC.GetGeneration(small)); // 1 (survived one GC)
Console.WriteLine(GC.GetTotalAllocatedBytes() > 100_000_000); // True
Console.WriteLine(System.Runtime.GCSettings.IsServerGC);       // False in a console app

static async Task<int> GetAsync(bool cached)
{
    if (cached) return 42;              // completes synchronously
    await Task.Delay(10);
    return 7;
}

Task<int> t = GetAsync(true);
Console.WriteLine(t.IsCompleted);       // True: no suspension happened

await Task.Delay(10).ConfigureAwait(false); // resume on any pool thread
Console.WriteLine(SynchronizationContext.Current is null); // True (console app)

var both = Task.WhenAll(Task.Run(() => throw new InvalidOperationException("a")),
                       Task.Run(() => throw new ArgumentException("b")));
try { await both; }
catch (Exception ex)
{
    Console.WriteLine(ex.GetType().Name);                 // InvalidOperationException (first)
    Console.WriteLine(both.Exception!.InnerExceptions.Count); // 2
}

static ValueTask<int> CachedAsync(int key) =>
    key == 0 ? ValueTask.FromResult(0) : new ValueTask<int>(GetAsync(false));
Console.WriteLine(await CachedAsync(0) + await CachedAsync(1)); // 7

